DOC=REPO+'/blob/main/docs/'
SOURCE='https://github.com/gabrielekarra/openDuet/archive/refs/tags/v0.4.0rc4.tar.gz'
MAC=f"uv tool install --python 3.12 'openduet[mac] @ {SOURCE}'\nopenduet setup --background --open"
SERVER='docker compose up -d --build'
