def render(lang):
 c=COPY[lang];url=ORIGIN+('/it/' if lang=='it' else '/')
 tabs=''.join(f'<button role="tab" aria-selected="{str(i==0).lower()}" aria-controls="tour-panel" data-scene="{i}" id="scene-{i}">{h(t)}</button>' for i,t in enumerate(c['views']))
 modelnames=''.join(f'<li>{h(t)}</li>' for t in c['models'])
 faqs=''.join(f'<details><summary>{h(q)}</summary><p>{h(a)}</p></details>' for q,a in c['faqs'])
 config={k:c[k] for k in ('requests','captions','screenalts','sample','copied','copyfailed','shared','sharefailed','macnote','servernote','guides')}
 config.update(lang=lang,commands=[MAC,SERVER],guideLinks=[DOC+'QUICKSTART-MAC'+('.it' if lang=='it' else '')+'.md',DOC+'SELF-HOSTING.md'])
 schema={'@context':'https://schema.org','@type':'SoftwareSourceCode','name':'OpenDuet','description':c['description'],'codeRepository':REPO,'license':'https://opensource.org/license/mit','programmingLanguage':'Python','url':url}
 return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>OpenDuet — {h(c['title'])}</title>
<meta name="description" content="{h(c['description'])}"><meta name="robots" content="index,follow"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{ORIGIN}/"><link rel="alternate" hreflang="it" href="{ORIGIN}/it/"><link rel="alternate" hreflang="x-default" href="{ORIGIN}/">
<meta property="og:type" content="website"><meta property="og:site_name" content="OpenDuet"><meta property="og:title" content="OpenDuet — {h(c['title'])}"><meta property="og:description" content="{h(c['social'])}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/social-preview.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="OpenDuet: your bot, your models; actual sample workspace"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="OpenDuet — {h(c['title'])}"><meta name="twitter:description" content="{h(c['social'])}"><meta name="twitter:image" content="{ORIGIN}/assets/social-preview.png">
<link rel="icon" href="/assets/favicon.png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="preload" href="/assets/fonts/instrument-sans.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/styles.css"><script defer src="/site.js"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>
<body><a class="skip" href="#main">{'Vai al contenuto' if lang=='it' else 'Skip to content'}</a>
<header class="frame nav"><a class="brand" href="{'/it/' if lang=='it' else '/'}" aria-label="OpenDuet"><img src="/assets/mark.svg" alt="" width="58" height="29"><span>OpenDuet</span></a><nav aria-label="{'Navigazione' if lang=='it' else 'Main navigation'}"><a href="#demo">{c['nav'][0]}</a><a href="#work">{c['nav'][1]}</a><a href="#install">{c['nav'][2]}</a></nav><div class="nav-end"><a href="{c['other']}" lang="{'en' if lang=='it' else 'it'}">{c['language']}</a><a class="source-link" href="{REPO}" target="_blank" rel="noopener">GitHub <span aria-hidden="true"></span></a></div></header>
<main id="main"><section class="frame hero" aria-labelledby="hero-title"><div class="hero-copy"><h1 id="hero-title" class="reveal">{h(c['head'][0])}<br>{h(c['head'][1])}</h1><p class="hero-text reveal">{h(c['hero'])}</p><div class="hero-actions reveal"><a class="button" href="#install">{c['install']} <span aria-hidden="true"></span></a><a class="text-link" href="#demo">{c['watch']} <span aria-hidden="true"></span></a></div><p class="small hero-note">{h(c['license'])}</p></div>
<div class="tour reveal" id="tour"><div class="tour-tabs" role="tablist" aria-label="{'Il flusso' if lang=='it' else 'The workflow'}">{tabs}</div><div id="tour-panel" role="tabpanel" aria-labelledby="scene-0"><button class="screen-button" data-enlarge aria-label="{h(c['expand'])}"><img id="tour-image" src="/assets/chat-result.png" width="1440" height="1000" alt="{h(c['screenalts'][0])}" fetchpriority="high"></button><p id="tour-caption" class="image-caption">{h(c['captions'][0])} · {h(c['sample'])}</p></div><div class="request"><span class="small">{h(c['example'])}</span><p id="example-request">{h(c['requests'][0])}</p><div class="request-actions"><button class="text-control" id="copy-request">{c['copyrequest']} <span aria-hidden="true"></span></button><button class="text-control" id="share-workflow">{c['share']} <span aria-hidden="true"></span></button></div></div></div></section>
<section class="frame demo-section" id="demo" aria-labelledby="demo-title"><div class="section-intro"><h2 id="demo-title" class="reveal">{h(c['demohead'])}</h2><p class="reveal">{h(c['demotext'])}</p></div><div class="video-wrap reveal"><video controls playsinline preload="none" poster="/assets/chat-result.png" aria-label="OpenDuet demo"><source src="/assets/demo.mp4" type="video/mp4"><track kind="captions" srclang="{lang}" label="{'Italiano' if lang=='it' else 'English'}" src="/assets/demo-{lang}.vtt" default></video></div><div class="demo-notes"><p class="small">{h(c['democaption'])}</p><details><summary>{h(c['transcript'])}</summary><p>{h(c['transcripttext'])}</p></details></div></section>
<section class="field files" id="work" aria-labelledby="file-title"><div class="frame feature"><div class="feature-copy"><h2 id="file-title" class="reveal">{h(c['filehead'])}</h2><p class="reveal">{h(c['filetext'])}</p><a class="text-link" href="{DOC}MAKE.md">{c['filelink']} <span aria-hidden="true"></span></a><p class="file-formats">DOCX · PDF · XLSX<br>PPTX · HTML</p></div><figure class="reveal"><button class="screen-button" data-enlarge aria-label="{h(c['expand'])}"><img src="/assets/make-file.png" alt="{'Documenti generati nella vista Make' if lang=='it' else 'Generated documents in the Make view'}" width="1440" height="1000" loading="lazy"></button><figcaption class="image-caption">{h(c['filecaption'])}</figcaption></figure></div></section>
<section class="field dark" aria-labelledby="review-title"><div class="frame feature reverse"><figure class="reveal"><button class="screen-button" data-enlarge aria-label="{h(c['expand'])}"><img src="/assets/review-approval.png" alt="{'Contenuto esatto di un’azione da approvare' if lang=='it' else 'Exact payload of an action awaiting review'}" width="1440" height="1000" loading="lazy"></button><figcaption class="image-caption">{h(c['reviewcaption'])}</figcaption></figure><div class="feature-copy"><h2 id="review-title" class="reveal">{h(c['reviewhead'])}</h2><p class="reveal">{h(c['reviewtext'])}</p><a class="text-link" href="{DOC}VALIDATION.md">{c['reviewlink']} <span aria-hidden="true"></span></a></div></div></section>
<section class="frame models" aria-labelledby="model-title"><div class="section-intro"><h2 id="model-title" class="reveal">{h(c['modelhead'])}</h2><p class="reveal">{h(c['modeltext'])}</p></div><div class="model-body"><div><ul class="model-names">{modelnames}</ul><p class="small model-note">{h(c['modelnote'])}</p></div><figure class="reveal"><button class="screen-button" data-enlarge aria-label="{h(c['expand'])}"><img src="/assets/connections.png" alt="{'Directory di connettori OpenDuet' if lang=='it' else 'OpenDuet connector directory'}" width="1440" height="1000" loading="lazy"></button><figcaption class="image-caption">{h(c['connectcaption'])}</figcaption></figure></div></section>
<section class="field mac" aria-labelledby="mac-title"><div class="frame mac-body"><h2 id="mac-title" class="reveal">{h(c['machead'])}</h2><div class="reveal"><p>{h(c['mactext'])}</p><p class="small">{h(c['maccommands'])}</p><a class="text-link" href="{DOC}REMOTE-ACCESS.md">{c['maclink']} <span aria-hidden="true"></span></a></div></div></section>
<section class="frame install-section" id="install" aria-labelledby="install-title"><div><h2 id="install-title" class="reveal">{h(c['installhead'])}</h2><p class="reveal">{h(c['installtext'])}</p><p class="small">{h(c['cost'])}</p></div><div class="install-panel" data-ui><div class="install-tabs" role="tablist" aria-label="{'Piattaforma' if lang=='it' else 'Platform'}"><button role="tab" aria-selected="true" data-platform="0" aria-controls="install-content" id="platform-0">{c['installtabs'][0]}</button><button role="tab" aria-selected="false" data-platform="1" aria-controls="install-content" id="platform-1">{c['installtabs'][1]}</button></div><div id="install-content" role="tabpanel" aria-labelledby="platform-0"><pre><code id="install-command">{h(MAC)}</code></pre><button class="button copy-command" id="copy-install">{c['copycommand']} <span aria-hidden="true"></span></button><p class="small" id="install-note">{h(c['macnote'])}</p><a id="install-guide" class="text-link" href="{config['guideLinks'][0]}">{c['guides'][0]} <span aria-hidden="true"></span></a><noscript><p><a href="{DOC}SELF-HOSTING.md">{h(c['guides'][1])}</a></p></noscript></div></div></section>
<section class="frame faq-section" aria-labelledby="faq-title"><h2 id="faq-title" class="reveal">{h(c['faqhead'])}</h2><div>{faqs}</div></section></main>
<footer class="field dark"><div class="frame footer"><div class="footer-top"><p>{h(c['foot'])}<br><span class="small">{h(c['built'])}</span></p><div class="footer-links"><a href="#install">{c['footerlinks'][0]}</a><a href="{REPO}#readme">{c['footerlinks'][1]}</a><a href="{DOC}VALIDATION.md">{c['footerlinks'][2]}</a><a href="{DOC}LAUNCH-KIT.md">{c['footerlinks'][3]}</a></div></div><p class="footer-name" aria-label="OpenDuet"><span class="footer-glasses" aria-hidden="true"></span>OpenDuet</p><p class="small footer-bottom">{h(c['release'])} <a href="{REPO}/blob/main/LICENSE">License</a></p></div></footer>
<dialog id="image-dialog" aria-label="{h(c['expand'])}"><form method="dialog"><button class="button">{c['close']}</button></form><img id="expanded-image" alt=""></dialog><div id="feedback" role="status" aria-live="polite" hidden></div><script type="application/json" id="page-config">{json.dumps(config,ensure_ascii=False)}</script></body></html>'''

if __name__=='__main__':
 dist=ROOT/'dist';dist.mkdir(exist_ok=True)
 shutil.copytree(ROOT/'assets',dist/'assets',dirs_exist_ok=True)
 for file in ('styles.css','site.js'):shutil.copy2(ROOT/file,dist/file)
 for lang in ('en','it'):
  target=dist/('it/index.html' if lang=='it' else 'index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(render(lang))
 (dist/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml\n')
 (dist/'sitemap.xml').write_text(f'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>{ORIGIN}/</loc></url><url><loc>{ORIGIN}/it/</loc></url></urlset>')
 print('Built EN/IT launch page in dist/')
